const rows = $input.all().map(i => i.json).filter(r => r && r.rating);
const fmt = (r) => '[' + (r.rating === 'up' ? 'positivo' : 'negativo') + '] usuário: "' +
  String(r.mensagem_usuario || '').slice(0, 200) + '" | resposta: "' +
  String(r.resposta_assistente || '').slice(0, 300) + '"' +
  (r.comentario ? ' | comentário: "' + String(r.comentario).slice(0, 300) + '"' : '');
const positivos = rows.filter(r => r.rating === 'up').length;
const negativos = rows.length - positivos;
const feedbackText = rows.length ? rows.slice(0, 100).map(fmt).join('\n') : '(sem feedbacks recentes)';
return [{ json: { total: rows.length, positivos, negativos, feedbackText } }];

// Sinais agregados + diretrizes atuais → 1 item por expertise (5 trilhas)
const sig = $('Agregar Sinais').first()?.json ?? {};
const lessonRows = $input.all().map(i => i.json).filter(r => r && typeof r.licoes === 'string' && r.licoes.trim());
const licoesAtuais = lessonRows.length ? lessonRows[0].licoes : '(nenhuma diretriz registrada ainda)';

// PREENCHA com os IDs das 5 pastas de Trilha no Drive (uma por expertise).
// São as FONTES dos 5 notebooks no NotebookLM — NÃO use as mesmas pastas do RAG.
const PASTAS = {
  'SEO Técnico':              '1mP18gdTyW3qUn34pM511dw5wetpUetwR',
  'Estratégia':               '18Hls3xIV45jLU_OzFpI2u6CiCBwLLUEl',
  'Conteúdo & Link Building': '13e_zShBKiDxg0h13dzwmnqU1t8LfpqjT',
  'Retail Search':            '1JUcUW6f37tfTp-rFg4O_gaqAktzsVGgC',
  'GEO':                      '123zt14C4BdbY8heFzWjPKHSlyVx6mT4K'
};
const ESCOPO = {
  'SEO Técnico': 'Indexação, crawl budget, arquitetura de informação, Core Web Vitals/performance, dados estruturados, status codes, sitemaps e robots.',
  'Estratégia': 'Priorização e roadmap de SEO, análise competitiva, posicionamento, definição de KPIs e construção de business case.',
  'Conteúdo & Link Building': 'Produção editorial, clusters de tópicos/keywords, E-E-A-T, construção de autoridade, link building e digital PR.',
  'Retail Search': 'SEO para e-commerce e marketplaces, páginas de categoria e PDP, busca interna, feeds de produto e interface com retail media.',
  'GEO': 'Visibilidade em engines generativas (ChatGPT, Gemini, Perplexity), citações, query fan-out, mapeamento de prompts, agentic browsing e llms.txt.'
};
const hoje = new Date().toISOString().slice(0, 10);
return Object.keys(ESCOPO).map(exp => ({ json: {
  expertise: exp,
  escopo: ESCOPO[exp],
  trilhaFolderId: PASTAS[exp] || '',
  titulo: hoje + ' — Trilha ' + exp,
  total: sig.total ?? 0,
  positivos: sig.positivos ?? 0,
  negativos: sig.negativos ?? 0,
  feedbackText: sig.feedbackText ?? '(sem feedbacks recentes)',
  licoesAtuais
} }));

