const out = String($json.output ?? '').trim();
const src = $('Preparar Trilhas').item.json;
const body = out || ('# Trilha ' + (src.expertise || '') + '\n\nSem conteúdo gerado nesta execução.');
return { json: {
  body,
  title: src.titulo,
  folderId: src.trilhaFolderId,
  expertise: src.expertise,
  skip: !src.trilhaFolderId
} };
